'use strict';
const mode=document.body.dataset.mode,API='api.php';
let state=null,view=mode==='control'?'studio':'home',selectedCourse='s1-1',courseTab='learn',selectedSession=1,modalOpen=false,busy=false,polling=false,lastVersion=-1,screenKey='',serverOffset=0,autoCheckin=false;
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const base=new URL('./',location.href),learnerLink=new URL('index.html?checkin=1',base).href;
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').hidden=true,5000);}
function validURL(u){try{const v=new URL(u,base);return ['https:','http:'].includes(v.protocol)?v.href:'#';}catch{return '#';}}
function assetURL(a){if(!a||!/^workshop-media\/[a-f0-9]{32}\.(jpg|jpeg|png|webp|gif|mp4|webm|pdf|txt|docx)$/.test(a.url))return '#';return new URL(a.url,base).href;}
function qrHTML(link,size=250){try{const q=qrcode(0,'M');q.addData(link);q.make();return '<div class="qr" style="max-width:'+size+'px">'+q.createImgTag(5,4,'Quét QR vào lớp')+'</div>';}catch{return '<a href="'+esc(link)+'">'+esc(link)+'</a>';}}
async function api(action,body){const r=await fetch(API+'?action='+encodeURIComponent(action),{cache:'no-store',credentials:'same-origin',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,csrf:state?.csrf})}:{})});if(r.redirected)throw Error('API bị chuyển hướng. Kiểm tra cấu hình hosting.');let v;try{v=await r.json();}catch{throw Error('API chưa trả về dữ liệu JSON. Kiểm tra tệp PHP và lỗi hosting.');}if(!r.ok||v.error)throw Error(v.error||'Không thực hiện được yêu cầu.');return v;}
async function sync(force=false){try{const next=await api('state');const changed=force||!state||next.version!==lastVersion||next.admin!==state.admin;next.participant_count=next.checked_in_count??next.participant_count;state=next;lastVersion=next.version;serverOffset=next.server_time-Math.floor(Date.now()/1000);$('status').textContent=mode==='screen'?'● Đồng bộ với màn điều khiển':'Đã kết nối · '+next.participant_count+' người kiểm diện';if(changed)render();tick();if(mode==='learner'&&!autoCheckin){autoCheckin=true;if(new URL(location.href).searchParams.has('checkin')&&!state.me?.phone)checkinModal();}return true;}catch(e){$('status').textContent='● Chưa kết nối';if(!state)$('app').innerHTML='<div class="card"><h2>Chưa kết nối được lớp học</h2><div class="alert error">'+esc(e.message)+'</div><button class="btn primary" data-action="retry">Thử lại</button></div>';return false;}}
const labels={maket:'Maket ảnh / video',text:'Nội dung văn bản',document:'Tài liệu & hình ảnh',poll:'Khảo sát',game:'Trò chơi'};
function icon(name){const paths={studio:'M3 3h18v12H3z M7 21h10 M12 15v6',maket:'M3 4h18v16H3z M3 16l5-5 4 4 4-6 5 7 M8 8h.01',attendance:'M8 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M2 21v-3a6 6 0 0 1 12 0v3 M16 8h6 M19 5v6',poll:'M4 20V10 M10 20V4 M16 20V8 M22 20H2',game:'M7 8h10a5 5 0 0 1 5 5l-1 6-5-3H8l-5 3-1-6a5 5 0 0 1 5-5 M6 11v5 M3.5 13.5h5 M16 12h.1 M19 15h.1',course:'M3 3h7a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H3z M13 6a3 3 0 0 1 3-3h6v16h-5a4 4 0 0 0-4 2',tools:'M4 4h6v6H4z M14 4h6v6h-6z M4 14h6v6H4z M14 14h6v6h-6z',settings:'M12 3l2 3 4-1 1 4 3 3-3 2 1 4-4 1-4 3-2-3-4 1-1-4-3-3 3-2-1-4 4-1z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',ai:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',project:'M3 3h18v13H3z M8 21h8 M12 16v5 M10 7l5 3-5 3z'};return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[name]||paths.studio)+'"/></svg>';}
function aiButton(task,label='AI hỗ trợ',id=''){return '<button type="button" class="btn ai small" data-action="ai" data-task="'+task+'" '+(id?'data-id="'+id+'"':'')+'>'+icon('ai')+label+'</button>';}
function projectButton(title,body,label='Chiếu'){return '<button type="button" class="btn small" data-action="project-text" data-title="'+esc(title)+'" data-body="'+esc(body)+'">'+icon('project')+label+'</button>';}
function settingsView(){const a=state.ai||{provider:'gemini',model:'gemini-2.5-flash',has_key:false};return '<div class="title-row"><div><span class="eyebrow">MỘT KHÓA · TOÀN BỘ BẢNG ĐIỀU KHIỂN</span><h1 style="font-size:35px;margin:10px 0">Cài đặt AI</h1></div></div><div class="grid two"><div class="card"><form id="aiSettings"><label class="field">Nhà cung cấp</label><select name="provider" id="aiProvider"><option value="gemini" '+(a.provider==='gemini'?'selected':'')+'>Google Gemini</option><option value="openai" '+(a.provider==='openai'?'selected':'')+'>OpenAI</option></select><label class="field">Khóa API</label><input name="key" id="aiKey" type="password" autocomplete="off" placeholder="'+(a.has_key?'Đã lưu khóa · để trống nếu giữ nguyên':'Dán khóa API tại đây')+'"><label class="field">Model (đã điền sẵn, có thể đổi)</label><input name="model" id="aiModel" value="'+esc(a.model)+'"><div class="actions" style="margin-top:20px"><button class="btn primary">Lưu cài đặt</button><button type="button" class="btn" data-action="ai-test">Kiểm tra kết nối</button></div><p class="note">Khóa được mã hóa và lưu trên hosting, không trả cho học viên. Không cần nhập lại ở từng chức năng.</p><p class="note">Gói ChatGPT/Gemini cá nhân và hạn mức API có thể khác nhau; dùng khóa có quyền gọi model đã chọn.</p></form></div><div class="card"><span class="badge '+(a.has_key?'live':'')+'">'+(a.has_key?'Đã lưu khóa':'Chưa cấu hình')+'</span><h3 style="margin:20px 0">AI hỗ trợ mọi bước</h3><div class="point"><strong>Maket & nội dung</strong><p>Soạn lời dẫn, kịch bản, gợi ý thiết kế; tạo nội dung chia trang.</p></div><div class="point"><strong>Kiểm diện</strong><p>Gợi ý tổ chức lớp từ tổng số, nhóm chức vụ và đơn vị.</p></div><div class="point"><strong>Khảo sát & trò chơi</strong><p>Tạo câu hỏi, phương án, giải thích; phân tích kết quả tổng hợp.</p></div><div class="point"><strong>Điều khiển & chuyên môn</strong><p>Gợi ý nhịp trình bày, kiểm tra nội dung, tóm tắt và hoàn thiện tài liệu.</p></div>'+ (a.notice?'<div class="alert">'+esc(a.notice)+'</div>':'')+'</div></div>';}
let aiDraft=null,aiTask='draft',aiSnapshot=null;
function aiModal(task='draft',id=''){const form=$('editorForm');aiSnapshot=form?Object.fromEntries(new FormData(form)):null;aiTask=task;aiDraft=null;const item=id?state.studio.items.find(x=>x.id===id):null;if(!aiSnapshot&&item)aiSnapshot={id:'',type:item.type,title:item.title,body:item.body,options:item.options.join('\n'),answer:item.answer||0,seconds:item.seconds||30,explanation:item.explanation||'',asset:item.asset?.id||'',fit:item.fit||'cover'};const defaults={maket:'Soạn lời dẫn mở đầu và gợi ý thiết kế maket xanh sáng về tập huấn AI trong quản lý trường học.',attendance:'Gợi ý chia nhóm thực hành và tổ chức kiểm diện dựa trên số liệu tổng hợp.',survey:'Tạo một khảo sát về nhu cầu sử dụng AI của cán bộ quản lý trường phổ thông, 4 phương án.',game:'Tạo một câu hỏi tình huống về kiểm chứng kết quả AI trong quản lý trường học, 4 phương án và giải thích.',outline:'Soạn nội dung tập huấn rõ ràng, chia thành các trang bằng dòng ---.',analyze:'Phân tích phân bố lựa chọn, nêu giới hạn và đề xuất nội dung tập huấn tiếp theo. Không suy diễn nguyên nhân.',improve:'Kiểm tra và cải thiện nội dung: rõ ràng, đúng đối tượng, có ví dụ và nhiệm vụ thực hành.',tools:'Gợi ý cách hướng dẫn công cụ từ cơ bản đến nâng cao cho cán bộ quản lý.',controls:'Đề xuất trình tự điều khiển lớp và nhịp các hoạt động.',draft:'Soạn nội dung phù hợp cán bộ quản lý trường phổ thông.'};modal('Trợ lý AI · '+({survey:'Khảo sát',game:'Trò chơi',attendance:'Kiểm diện',analyze:'Phân tích kết quả',maket:'Maket',outline:'Nội dung tập huấn'}[task]||'Hỗ trợ công việc'),'<form id="aiPromptForm"><input type="hidden" name="task" value="'+task+'"><input type="hidden" name="item" value="'+(id||state.studio.active?.id||'')+'"><input type="hidden" name="course" value="'+(view==='course'?selectedCourse:'')+'"><label class="field">Yêu cầu / tài liệu nguồn</label><textarea name="prompt" maxlength="12000" style="min-height:160px" required>'+esc(defaults[task]||defaults.draft)+(item&&!aiSnapshot?'\n\nNội dung cần cải thiện: '+esc(item.title)+'\n'+esc(item.body):'')+(aiSnapshot?'\n\nNội dung đang soạn: '+esc(aiSnapshot.title||'')+'\n'+esc(aiSnapshot.body||''):'')+'</textarea><p class="note">Tự động dùng bối cảnh và kết quả tổng hợp; không tự gửi tên hoặc số điện thoại học viên. AI tạo bản nháp để thầy kiểm tra trước khi sử dụng.</p><button class="btn primary">'+icon('ai')+'Tạo với AI</button><span id="aiWorking" class="ai-working"></span></form><div id="aiResult" style="margin-top:20px"></div>',true);}
function showAIDraft(){if(!$('aiResult'))return;const d=aiDraft;const text=d.title+'\n\n'+d.body+(d.options.length?'\n\n'+d.options.map((x,i)=>String.fromCharCode(65+i)+'. '+x).join('\n'):'')+(d.explanation?'\n\n'+d.explanation:'')+(d.visual_prompt?'\n\nGợi ý hình ảnh: '+d.visual_prompt:'');$('aiResult').innerHTML='<div class="ai-output">'+esc(text)+'</div><div class="actions" style="margin-top:15px"><button class="btn primary" data-action="ai-apply">Đưa vào biểu mẫu</button><button class="btn" data-action="ai-project">Chiếu bản nháp</button><button class="btn" data-action="ai-copy">Sao chép</button></div>';}
function applyAIDraft(){const d=aiDraft;if(!d)return;const snap=aiSnapshot;let type=snap?.type||({survey:'poll',game:'game',maket:'text'}[aiTask]||'text');editor('',type);const form=$('editorForm');if(snap)for(const [k,v]of Object.entries(snap)){const el=form.elements.namedItem(k);if(el&&k!=='id')el.value=v;}form.elements.namedItem('type').value=type;form.elements.namedItem('title').value=d.title;form.elements.namedItem('body').value=d.body+(d.visual_prompt?'\n\nGợi ý hình ảnh / video: '+d.visual_prompt:'');form.elements.namedItem('options').value=d.options.join('\n');form.elements.namedItem('answer').value=d.answer;form.elements.namedItem('seconds').value=d.seconds;form.elements.namedItem('explanation').value=d.explanation;$('questionFields').hidden=!['poll','game'].includes(type);toast('Đã đưa bản nháp vào biểu mẫu mới. Kiểm tra rồi Lưu.');}
function stageName(){const s=state.studio.stage;if(s.kind==='item')return state.studio.active?.title||'Nội dung';if(s.kind==='course')return state.outline.find(x=>x.id===s.item)?.title||'Nội dung tập huấn';if(s.kind==='message')return s.title||'Nội dung trình chiếu';return {welcome:'Màn chào mừng',attendance:'Kiểm diện bằng QR',blank:'Màn hình chờ'}[s.kind]||'Màn chiếu';}
function render(){if(mode==='screen'){renderScreen();return;}const nav=mode==='control'?[['studio','◈ Tổng điều khiển'],['maket','▣ Maket'],['attendance','◎ Kiểm diện'],['poll','▥ Khảo sát'],['game','◇ Trò chơi'],['course','▤ Nội dung tập huấn'],['products','◇ Sản phẩm'],['tools','↗ Công cụ'],['settings','⚙ Cài đặt AI']]:[['home','◈ Lớp học của tôi'],['live','● Đang diễn ra'],['course','▤ Nội dung 3 buổi'],['products','◇ Sản phẩm'],['tools','↗ Công cụ AI']];$('nav').innerHTML=nav.map(([id,t])=>'<button data-action="view" data-id="'+id+'" class="'+(view===id?'active':'')+'">'+icon(id)+t.replace(/^[^ ]+ /,'')+'</button>').join('');$('topActions').innerHTML=mode==='control'?aiButton('controls','AI hỗ trợ')+'<a class="btn primary" href="screen.html" target="_blank" rel="noopener">Mở màn trình chiếu ↗</a><a class="btn" href="index.html" target="_blank" rel="noopener">Học viên ↗</a><button class="btn" data-action="auth">'+(state.admin?'Quản trị':'Đăng nhập')+'</button>':'<button class="btn primary" data-action="checkin">'+(state.me?.phone?esc(state.me.name):'Kiểm diện / Vào lớp')+'</button><a class="btn" href="control.html">Điều khiển</a>';
if(document.activeElement?.closest('#app form'))return;
if(mode==='control'&&!state.admin){$('app').innerHTML='<section class="hero"><div><span class="eyebrow">KHÔNG GIAN BÁO CÁO VIÊN</span><h1>Một lớp học.<br><span>Hai màn hình.</span></h1><p class="muted">Soạn nội dung, tải tư liệu và điều khiển màn chiếu theo nhịp của thầy. Đăng nhập quản trị để bắt đầu.</p><button class="btn primary" data-action="auth">Đăng nhập điều khiển</button></div><div class="signal"><b>AI</b></div></section>';return;}
$('app').innerHTML=mode==='control'?controlView():learnerView();tick();}
function controlView(){if(view==='settings')return settingsView();if(view==='products')return learnerView();if(view==='attendance')return attendanceControl();if(view==='course')return courseView(true);if(view==='tools')return toolsView();const filter=['maket','poll','game'].includes(view)?view:null;const items=state.studio.items.filter(x=>!filter||x.type===filter);return '<div class="title-row"><div><span class="eyebrow">LIVE STUDIO · ĐIỀU KHIỂN</span><h1 style="font-size:35px;margin:10px 0">'+(filter?labels[filter]:'Không gian trình bày')+'</h1></div><button class="btn primary" data-action="editor" data-type="'+(filter||'text')+'">＋ Tạo nội dung</button></div><div class="cockpit"><div class="metric-card">'+icon('attendance')+'<span><strong>'+state.participant_count+'</strong><small>Người kiểm diện</small></span></div><div class="metric-card">'+icon('course')+'<span><strong>'+state.studio.items.length+'</strong><small>Nội dung tự tạo</small></span></div><div class="metric-card">'+icon('poll')+'<span><strong>'+state.studio.items.filter(x=>x.type==="poll").length+'</strong><small>Khảo sát</small></span></div><div class="metric-card">'+icon('game')+'<span><strong>'+state.studio.items.filter(x=>x.type==="game").length+'</strong><small>Câu trò chơi</small></span></div></div><div class="actions" style="margin-bottom:18px">'+aiButton(filter==="poll"?"survey":filter==="game"?"game":filter==="maket"?"maket":"draft","Tạo nội dung với AI")+'</div><div class="layout"><div><div class="card focused"><span class="badge live">ĐANG TRÊN MÀN CHIẾU</span><h2 style="margin:14px 0">'+esc(stageName())+'</h2><div class="preview-box"><iframe src="screen.html" title="Xem trước màn chiếu"></iframe></div><div class="actions" style="margin-top:14px"><button class="btn small" data-action="stage" data-op="welcome">Chào mừng</button><button class="btn small" data-action="stage" data-op="attendance">Kiểm diện QR</button><button class="btn small" data-action="stage" data-op="blank">Màn chờ</button></div></div><div class="title-row"><h2>'+ (filter?'Danh sách '+labels[filter]:'Nội dung tự tạo')+'</h2><span class="badge">'+items.length+' nội dung</span></div><div class="grid two">'+(items.length?items.map(itemCard).join(''):'<div class="empty">Bấm Tạo nội dung để thêm văn bản, ảnh, video, khảo sát hoặc câu hỏi trò chơi.</div>')+'</div></div><aside class="sticky">'+liveControls()+'<div class="card" style="margin-top:15px"><span class="eyebrow">TRUY CẬP HỌC VIÊN</span><div style="text-align:center;margin:16px 0">'+qrHTML(learnerLink,230)+'</div><p class="note">Quét để nhập họ tên, chức vụ, đơn vị và số điện thoại. Lưu xong tự vào lớp.</p><button class="btn" data-action="copy-link">Sao chép link vào lớp</button></div></aside></div>';}
function itemCard(x){return '<article class="card"><span class="badge '+(x.open?'live':'')+'">'+labels[x.type]+' · '+(x.open?'Đã mở':'Chưa mở')+'</span>'+ (x.asset?.kind==='image'?'<img class="media-thumb" src="'+esc(assetURL(x.asset))+'" alt="'+esc(x.title)+'">':'')+'<h3 style="margin:14px 0 10px">'+esc(x.title)+'</h3><p class="muted">'+esc(x.body.slice(0,110))+'</p><div class="actions"><button class="btn primary small" data-action="show" data-id="'+x.id+'">▶ Trình chiếu</button><button class="btn small" data-action="editor" data-id="'+x.id+'">Sửa</button><button class="btn small" data-action="clone" data-id="'+x.id+'">Nhân bản</button><button class="btn small" data-action="hide" data-id="'+x.id+'">Ẩn</button>'+aiButton('improve','AI chỉnh sửa',x.id)+'</div></article>';}
function liveControls(){const x=state.studio.active,s=state.studio.stage;let html='<div class="card"><span class="eyebrow">ĐIỀU KHIỂN NHANH</span><h3 style="margin:13px 0">'+esc(stageName())+'</h3>';if(x&&['poll','game'].includes(x.type)){html+='<div class="actions">'+aiButton('analyze','AI phân tích',x.id)+(x.type==='game'?'<button class="btn primary" data-action="start" data-id="'+x.id+'">Bắt đầu '+x.seconds+' giây</button>':'<button class="btn primary" data-action="accept" data-id="'+x.id+'" data-value="1">Mở nhận khảo sát</button>')+'<button class="btn" data-action="stop" data-id="'+x.id+'">Đóng nhận</button><button class="btn violet" data-action="reveal" data-id="'+x.id+'" data-value="'+(x.reveal?'0':'1')+'">'+(x.reveal?'Ẩn kết quả':'Công bố kết quả')+'</button></div><p class="note">'+(x.accept?'Đang nhận trả lời':'Chưa nhận / đã đóng')+'</p><div class="timer" data-deadline="'+x.deadline+'"></div>'+statsHTML(x,true)+'<details style="margin-top:16px"><summary>Học viên kiểm diện · '+(state.studio.roster||[]).filter(p=>p.answered).length+'/'+(state.studio.roster||[]).length+' đã trả lời</summary>'+ (state.studio.roster||[]).map(p=>'<div class="point"><strong>'+esc(p.name)+'</strong><p>'+esc(p.school)+' · '+(p.answered?'✓ Đã trả lời':'Chưa trả lời')+'</p></div>').join('')+'</details>';}
if(x?.asset?.kind==='video')html+='<div class="actions"><button class="btn primary" data-action="media" data-playing="'+(s.playing?'0':'1')+'">'+(s.playing?'Tạm dừng':'Phát video')+'</button><button class="btn" data-action="sound">'+(s.sound?'Tắt âm':'Bật âm')+'</button><button class="btn" data-action="restart">Phát lại từ đầu</button></div><p class="note">Trên màn chiếu, bấm Bật âm thanh / video một lần nếu trình duyệt yêu cầu.</p>';
if(x&&(x.asset?.kind==='pdf'||['text','document'].includes(x.type)))html+='<div class="actions"><button class="btn" data-action="page" data-step="-1">← Trang trước</button><span class="badge">Trang '+((s.slide||0)+1)+'</span><button class="btn" data-action="page" data-step="1">Trang tiếp →</button></div>';
if(s.kind==='course')html+='<div class="actions">'+[['learn','Nội dung'],['case','Tình huống'],['practice','Thực hành'],['prompt','Câu lệnh']].map(([page,t])=>'<button class="btn small" data-action="course-show" data-id="'+s.item+'" data-page="'+page+'">'+t+'</button>').join('')+'</div>';
return html+'<div class="actions" style="margin-top:18px"><button class="btn small" data-action="timer-modal">Đồng hồ thực hành</button><button class="btn small" data-action="announce-modal">Thông báo</button></div><div class="timer" data-deadline="'+state.controls.timer+'"></div></div>';}
function attendanceControl(){return '<div class="title-row"><div><span class="eyebrow">KIỂM DIỆN & TÀI KHOẢN</span><h1 style="font-size:35px;margin:10px 0">Chào đón học viên</h1></div><div class="actions"><button class="btn primary" data-action="stage" data-op="attendance">Chiếu mã QR</button><button class="btn" data-action="participants">Danh sách & xuất CSV</button>'+aiButton('attendance','AI tổ chức lớp')+'</div></div><div class="grid two"><div class="card" style="text-align:center">'+qrHTML(learnerLink,350)+'<p class="note">'+esc(learnerLink)+'</p><button class="btn" data-action="copy-link">Sao chép link</button></div><div class="card"><div class="metrics"><strong>'+state.participant_count+'</strong><span>học viên đã ghi nhận</span></div><div class="info">Tài khoản = số điện thoại.<br>Mật khẩu ban đầu = tên gọi không dấu, viết thường + 3 số cuối điện thoại.<br>Ví dụ: Nguyễn Hồng Dân, 0888770799 → dan799.</div><p class="muted">Số điện thoại không hiển thị trên màn trình chiếu. Danh sách đầy đủ chỉ dành cho quản trị.</p>'+state.studio.attendance.map(p=>'<div class="point"><strong>'+esc(p.name)+'</strong><p>'+esc(p.role)+' · '+esc(p.school)+'</p></div>').join('')+'</div></div>';}
function hero(){return '<section class="hero"><div><span class="eyebrow">TỪ HIỂU ĐÚNG ĐẾN LÀM ĐƯỢC</span><h1>Quản trị trường học<br>trong thời đại <span>AI.</span></h1><p class="muted">Trải nghiệm tình huống quản lý, tương tác cùng báo cáo viên và tạo sản phẩm phục vụ nhà trường.</p><div class="metrics"><span><strong>03</strong> buổi học</span><span><strong>18</strong> phần nội dung</span><span><strong>'+state.participant_count+'</strong> người kiểm diện</span></div><div class="actions"><button class="btn primary" data-action="checkin">'+(state.me?.phone?'Tài khoản của tôi':'Kiểm diện & vào lớp')+'</button><button class="btn" data-action="view" data-id="course">Khám phá nội dung</button></div></div><div class="signal"><b>AI</b></div></section>';}
function learnerView(){if(view==='course')return courseView(false);if(view==='tools')return toolsView();if(view==='products')return '<div class="title-row"><h2>Sản phẩm được chia sẻ</h2></div><div class="grid two">'+(state.gallery.length?state.gallery.map(p=>'<div class="card"><h3>'+esc(p.name)+'</h3><small class="muted">'+esc(p.school)+'</small><div class="content-body">'+esc(p.submission)+'</div>'+(p.link?'<a class="btn" href="'+esc(validURL(p.link))+'" target="_blank" rel="noopener">Mở sản phẩm ↗</a>':'')+(mode==='control'?projectButton('Sản phẩm · '+p.name,p.submission+(p.link?'\n\n'+validURL(p.link):'')):'')+'</div>').join(''):'<div class="empty">Chưa có sản phẩm được báo cáo viên chọn chia sẻ.</div>')+'</div>';
const active=state.studio.active;return (view==='home'?hero():'<div class="title-row"><h1 style="font-size:34px">Đang diễn ra</h1></div>')+(state.controls.announcement?'<div class="info">'+esc(state.controls.announcement)+'</div>':'')+'<div class="title-row"><h2>'+esc(stageName())+'</h2><span class="badge live">Theo nhịp báo cáo viên</span></div>'+(active?learnerItem(active):state.studio.stage.kind==='course'?renderCourse(state.sections.find(x=>x.id===state.studio.stage.item),false):'<div class="card"><h3>'+ (state.me?.phone?'Thầy/cô đã vào lớp':'Sẵn sàng tham gia')+'</h3><p class="muted">'+(state.me?.phone?'Nội dung, khảo sát và trò chơi sẽ xuất hiện khi báo cáo viên mở.':'Kiểm diện bằng họ tên, chức vụ, đơn vị và số điện thoại để gửi câu trả lời.')+'</p></div>')+'<div class="title-row"><h2>Nội dung đã mở</h2></div><div class="grid">'+state.studio.items.filter(x=>x.id!==active?.id).map(x=>'<article class="card"><span class="badge">'+labels[x.type]+'</span><h3 style="margin:14px 0">'+esc(x.title)+'</h3><button class="btn" data-action="item-view" data-id="'+x.id+'">Xem nội dung</button></article>').join('')+'</div>';}
function mediaMarkup(x,screen=false){if(!x.asset)return '';const a=x.asset,u=esc(assetURL(a));if(a.kind==='image')return '<img class="'+(screen?'screen-media':'asset-preview')+'" style="object-fit:'+x.fit+'" src="'+u+'" alt="'+esc(x.title)+'">';if(a.kind==='video')return '<video '+(screen?'id="stageVideo" class="screen-media" playsinline muted loop':'class="asset-preview" controls playsinline')+' style="object-fit:'+x.fit+'" src="'+u+'"></video>';if(a.kind==='pdf')return '<iframe class="'+(screen?'screen-pdf':'asset-preview')+'" style="'+(!screen?'height:500px;max-height:none;':'')+'" src="'+u+(screen?'#page='+((state.studio.stage.slide||0)+1)+'&toolbar=0':'')+'" title="'+esc(a.name)+'"></iframe>';return '<div class="info">'+esc(a.name)+'<br><a class="btn" href="'+u+'" target="_blank" rel="noopener">'+(a.kind==='word'?'Tải Word để xem đầy đủ':'Mở tài liệu')+' ↗</a>'+(a.kind==='word'?'<p class="note">Để chiếu trực tiếp nhiều trang, xuất tài liệu Word thành PDF rồi tải lên.</p>':'')+'</div>';}
function learnerItem(x){const mine=state.studio.mine[x.id],closed=!x.accept||x.reveal||(x.type==='game'&&x.deadline<=state.server_time),disabled=closed||(x.type==='game'&&mine);return '<div class="card focused"><span class="eyebrow">'+labels[x.type]+'</span><h2 style="margin:15px 0">'+esc(x.title)+'</h2>'+mediaMarkup(x)+'<div class="content-body">'+esc(x.body)+'</div>'+(['poll','game'].includes(x.type)?'<div class="timer" data-deadline="'+x.deadline+'"></div><form class="voteForm" data-id="'+x.id+'">'+x.options.map((o,i)=>'<label class="choice '+(x.reveal&&x.type==='game'&&x.answer===i?'correct':'')+'"><input type="radio" name="choice" value="'+i+'" '+(mine?.choice===i?'checked':'')+' '+(disabled?'disabled':'')+' required><span>'+String.fromCharCode(65+i)+'. '+esc(o)+'</span></label>').join('')+'<button class="btn primary" '+(disabled?'disabled':'')+'>'+ (mine?'Đã gửi'+(x.type==='poll'?' · có thể cập nhật':''):'Gửi câu trả lời')+'</button></form><p class="note">'+(closed?'Chưa mở nhận hoặc đã kết thúc.':'Đang nhận trả lời'+(x.type==='game'?' · mỗi tài khoản trả lời một lần.':'.'))+'</p>'+statsHTML(x,false)+(x.reveal&&x.type==='game'?rankHTML(state.studio.ranking):''):'')+'</div>';}
function statsHTML(x,admin=false){if(!x.reveal&&!admin)return '<p class="note">Kết quả sẽ hiện khi báo cáo viên công bố.</p>';const v=state.studio.stats[x.id]||{total:0,counts:x.options.map(()=>0)};return '<div class="info">'+(x.reveal&&x.type==='game'?'<strong>Đáp án: '+String.fromCharCode(65+x.answer)+'. '+esc(x.options[x.answer])+'</strong><br>'+esc(x.explanation):'')+'<p class="note">'+v.total+' người trả lời</p>'+v.counts.map((n,i)=>'<div class="bar"><div class="bar-head"><span>'+String.fromCharCode(65+i)+'. '+esc(x.options[i])+'</span><strong>'+n+' · '+(v.total?Math.round(n/v.total*100):0)+'%</strong></div><div class="track"><div class="fill" style="width:'+(v.total?n/v.total*100:0)+'%"></div></div></div>').join('')+'</div>';}
function rankHTML(rows){return '<h3 style="margin-top:25px">Bảng điểm trò chơi</h3>'+rows.slice(0,10).map((p,i)=>'<div class="rank"><b>'+(['🥇','🥈','🥉'][i]||i+1)+'</b><span class="name">'+esc(p.name)+'<small>'+esc(p.school)+'</small></span><span class="score">'+p.score+'</span></div>').join('');}
function courseView(admin){return '<div class="title-row"><div><span class="eyebrow">NỘI DUNG TẬP HUẤN</span><h1 style="font-size:34px;margin:10px 0">Ba buổi · Một hành trình</h1></div>'+(admin?'<div class="actions">'+aiButton('outline','AI soạn bài')+'<button class="btn primary" data-action="editor" data-type="document">＋ Thêm văn bản / ảnh</button></div>':'')+'</div><div class="tabs">'+state.sessions.map(s=>'<button class="btn '+(selectedSession===s.id?'selected':'')+'" data-action="session" data-id="'+s.id+'">Buổi '+s.id+' · '+esc(s.title)+'</button>').join('')+'</div><div class="layout"><div>'+state.outline.filter(x=>x.session===selectedSession).map(x=>'<div class="admin-row"><div class="grow"><strong>'+esc(x.title)+'</strong><small>'+esc(x.level)+' · '+x.minutes+' phút · '+(state.controls.open[x.id]?'Đã mở':'Chưa mở')+'</small></div><button class="btn small" data-action="course" data-id="'+x.id+'">Xem</button>'+(admin?'<button class="btn primary small" data-action="course-show" data-id="'+x.id+'" data-page="learn">Chiếu</button>':'')+'</div>').join('')+'</div><aside>'+ (admin?liveControls():'<div class="card"><h3>Sản phẩm từng buổi</h3>'+state.sessions.map(x=>'<div class="point"><strong>Buổi '+x.id+'</strong><p>'+esc(x.outcome)+'</p></div>').join('')+'</div>')+'</aside></div>'+renderCourse(state.sections.find(x=>x.id===selectedCourse),admin);}
function renderCourse(s,admin){if(!s)return '<div class="empty" style="margin-top:20px">Phần này chưa được báo cáo viên mở.</div>';const tabs=[['learn','Nội dung'],['case','Tình huống'],['practice','Thực hành'],['prompt','Câu lệnh & công cụ']];let body='';if(courseTab==='learn')body=s.points.map((p,i)=>'<div class="point"><div class="sub-actions"><strong>'+esc(p[0])+'</strong>'+(admin?'<button class="btn mini-project" data-action="course-show" data-id="'+s.id+'" data-page="learn" data-highlight="'+i+'">'+icon('project')+'Chiếu</button>':'')+'</div><p>'+esc(p[1])+'</p></div>').join('')+'<div class="model">'+s.model.map(x=>'<span>'+esc(x)+'</span>').join('')+(admin?projectButton('Mô hình · '+s.title,s.model.join(' → ')):'')+'<div class="info">Sản phẩm: '+esc(s.deliverable)+(admin?projectButton('Sản phẩm cần hoàn thành',s.deliverable):'')+'</div>';if(courseTab==='case'){body='<h3>'+esc(s.case.title)+'</h3><p class="muted">'+esc(s.case.story)+'</p><strong>'+esc(s.question)+'</strong><form id="legacyVote" data-id="'+s.id+'">'+s.options.map((x,i)=>'<label class="choice"><input type="radio" name="choice" value="'+i+'" '+(state.mine[s.id]?.choice===i?'checked':'')+' required>'+String.fromCharCode(65+i)+'. '+esc(x)+'</label>').join('')+'<button class="btn primary" '+(!state.controls.accept[s.id]?'disabled':'')+'>Gửi lựa chọn</button></form>'+(state.controls.reveal[s.id]?'<div class="info">'+esc(s.explanation)+'</div>':'');}if(courseTab==='practice')body='<ol>'+s.task.map((x,i)=>'<li>'+esc(x)+(admin?projectButton('Nhiệm vụ '+(i+1)+' · '+s.title,x):'')+'</li>').join('')+'</ol><div class="info">'+esc(s.deliverable)+'<br>Tiêu chí: '+s.rubric.map(esc).join(' · ')+(admin?projectButton('Sản phẩm & tiêu chí · '+s.title,s.deliverable+'\n\n'+s.rubric.join('\n')):'')+'</div><form id="legacyProduct" data-id="'+s.id+'"><label class="field">Mô tả sản phẩm / câu lệnh</label><textarea name="submission" maxlength="6000">'+esc(state.mine[s.id]?.submission||'')+'</textarea><label class="field">Liên kết sản phẩm</label><input name="link" type="url" value="'+esc(state.mine[s.id]?.link||'')+'"><label class="check"><input type="checkbox" name="share">Đồng ý chia sẻ sản phẩm trong lớp</label><button class="btn primary" '+(!state.controls.accept[s.id]?'disabled':'')+'>Gửi bài</button></form>';if(courseTab==='prompt')body='<div class="content-body">'+esc(s.prompt)+'</div><div class="actions"><button class="btn" data-action="copy-prompt" data-id="'+s.id+'">Sao chép câu lệnh</button></div><div class="grid two" style="margin-top:18px">'+s.tools.map(id=>state.tools.find(x=>x.id===id)).filter(Boolean).map(toolCard).join('')+'</div>';
return '<div class="card" style="margin-top:22px"><span class="eyebrow">BUỔI '+s.session+'</span><h2 style="margin:12px 0">'+esc(s.title)+'</h2><p class="muted">'+esc(s.lead)+'</p><div class="tabs">'+tabs.map(([id,t])=>'<button class="btn '+(id===courseTab?'selected':'')+'" data-action="course-tab" data-id="'+id+'">'+t+'</button>').join('')+'</div>'+(admin?'<div class="actions">'+aiButton('improve','AI hỗ trợ phần này')+'<button class="btn primary" data-action="course-show" data-id="'+s.id+'" data-page="'+courseTab+'">Chiếu phần này</button><button class="btn" data-action="legacy-accept" data-id="'+s.id+'" data-value="'+(state.controls.accept[s.id]?'0':'1')+'">'+(state.controls.accept[s.id]?'Đóng nhận bài':'Mở nhận bài')+'</button><button class="btn" data-action="legacy-reveal" data-id="'+s.id+'" data-value="'+(state.controls.reveal[s.id]?'0':'1')+'">'+(state.controls.reveal[s.id]?'Ẩn gợi ý':'Công bố gợi ý')+'</button></div>':'')+body+'</div>';}
function toolCard(t){return '<article class="card"><span class="badge">'+esc(t.tier)+'</span><h3 style="margin:14px 0">'+esc(t.name)+'</h3><p class="muted">'+esc(t.use)+'</p><div class="actions"><a class="btn" href="'+esc(validURL(t.url))+'" target="_blank" rel="noopener">Mở công cụ ↗</a>'+(state.admin?projectButton(t.name,t.use+'\n'+t.url):'')+'</div></article>';}
function toolsView(){return '<div class="title-row"><h1 style="font-size:35px">Công cụ AI & tài nguyên</h1>'+(state.admin?aiButton('tools','AI hướng dẫn công cụ'):'')+'</div><div class="grid">'+state.tools.map(toolCard).join('')+'</div><div class="card" style="margin-top:22px"><h3>Dữ liệu thực hành giả lập</h3>'+ (state.admin?projectButton('Dữ liệu thực hành giả lập','Tải CSV mẫu trong mục Công cụ & tài nguyên. Thực hành tổng hợp, phân tích dữ liệu và kiểm chứng kết quả AI.'):'')+'<a class="btn" href="sample-data.csv" download>Tải CSV mẫu</a><p class="note">Công cụ mở riêng; trang không dùng hoặc chia sẻ mật khẩu tài khoản AI.</p></div>';}
function renderScreen(){const ss=state.studio,s=ss.stage,x=ss.active;let key=JSON.stringify(x?.type==='maket'?{...s,playing:undefined,sound:undefined}:s)+(x?.type==='maket'?'':':'+state.version);if(key===screenKey){applyMedia();return;}screenKey=key;let content='';if(s.kind==='message'){content='<div class="screen-content"><span class="eyebrow">NỘI DUNG TRÌNH CHIẾU</span><h1>'+esc(s.title)+'</h1><div class="content-body">'+esc(s.body)+'</div></div>';}else if(s.kind==='blank'){content='<div class="welcome"><span class="eyebrow">TẬP HUẤN ỨNG DỤNG AI</span><h1>Chờ một nhịp.<br>Khám phá điều mới.</h1></div>';}else if(s.kind==='attendance'){content='<div class="screen-content screen-attendance"><div><span class="eyebrow">KIỂM DIỆN · KẾT NỐI · SẴN SÀNG</span><h1>Quét QR.<br>Cùng vào lớp.</h1><div><span class="att-count">'+state.participant_count+'</span><span class="muted"> học viên đã kiểm diện</span></div><div class="att-people">'+ss.attendance.map(p=>'<div class="att-person">'+esc(p.name)+'<small>'+esc(p.role)+' · '+esc(p.school)+'</small></div>').join('')+'</div></div><div style="text-align:center">'+qrHTML(learnerLink,370)+'<p style="font-size:15px;color:var(--muted)">Họ tên · Chức vụ · Đơn vị · Số điện thoại</p></div></div>';}else if(s.kind==='item'&&x){if(x.type==='maket')content=mediaMarkup(x,true);else content='<div class="screen-content"><span class="eyebrow">'+labels[x.type]+'</span><h1>'+esc(x.title)+'</h1>'+mediaMarkup(x,true)+'<div class="content-body">'+esc(x.body.split(/\r?\n---\r?\n/)[s.slide||0]||x.body)+'</div>'+(['poll','game'].includes(x.type)?'<div class="timer" data-deadline="'+x.deadline+'"></div><div class="grid '+(x.reveal&&x.type==='game'?'two':'')+'"><div>'+(!x.reveal?x.options.map((o,i)=>'<div class="choice">'+String.fromCharCode(65+i)+'. '+esc(o)+'</div>').join(''):statsHTML(x))+'</div>'+(x.reveal&&x.type==='game'?'<div>'+rankHTML(ss.ranking.slice(0,3))+'</div>':'')+'</div><p style="font-size:16px;color:var(--cyan)">'+(x.reveal?'Đã công bố kết quả':x.accept?'Trả lời trên điện thoại của thầy/cô':'Chờ báo cáo viên bắt đầu')+'</p>':'')+'</div>';}else if(s.kind==='course'){const c=state.sections.find(c=>c.id===s.item);if(c){let body='';if(s.page==='learn')body=c.points.filter((p,i)=>s.highlight==null||s.highlight<0||s.highlight===i).map(p=>'<div class="point"><strong>'+esc(p[0])+'</strong><p>'+esc(p[1])+'</p></div>').join('');if(s.page==='case')body='<h2>'+esc(c.case.title)+'</h2><div class="content-body">'+esc(c.case.story)+'\n\n'+esc(c.question)+'</div><div class="grid two">'+c.options.map((x,i)=>'<div class="choice">'+String.fromCharCode(65+i)+'. '+esc(x)+'</div>').join('')+'</div>'+(state.controls.reveal[c.id]?'<div class="info">'+esc(c.explanation)+'</div>':'');if(s.page==='practice')body='<div class="content-body">'+c.task.map((x,i)=>(i+1)+'. '+x).map(esc).join('\n')+'</div><div class="info">'+esc(c.deliverable)+'</div>';if(s.page==='prompt')body='<div class="content-body">'+esc(c.prompt)+'</div>';content='<div class="screen-content"><span class="eyebrow">BUỔI '+c.session+' · '+esc(c.level)+'</span><h1>'+esc(c.title)+'</h1>'+body+'</div>';}}
if(!content)content='<div class="screen-content welcome"><div class="signal"><b>AI</b></div><span class="pill">CHƯƠNG TRÌNH TẬP HUẤN · CÁN BỘ QUẢN LÝ</span><h1>Ứng dụng trí tuệ nhân tạo<br>trong quản lý nhà trường</h1><p style="font-size:23px;color:var(--muted)">BCV Nguyễn Hồng Dân</p><p style="font-size:16px;color:var(--cyan)">Hiểu đúng · Vận hành tốt · Làm ra sản phẩm</p></div>';
$('app').innerHTML=content;applyMedia();}
let lastMediaVersion=null;
function applyMedia(){const v=$('stageVideo');if(!v)return;const s=state.studio.stage;if(lastMediaVersion!==s.media_version){v.currentTime=0;lastMediaVersion=s.media_version;}v.muted=!s.sound;if(s.playing&&v.paused)v.play().catch(()=>{});if(!s.playing&&!v.paused)v.pause();}
function modal(title,html,wide=false){modalOpen=true;$('modal').innerHTML='<div class="modal-back"><section class="modal '+(wide?'wide':'')+'" role="dialog" aria-modal="true"><div class="modal-head"><h2>'+title+'</h2><button class="close" data-action="close" aria-label="Đóng">×</button></div>'+html+'<footer class="footer">TẬP HUẤN ỨNG DỤNG TRÍ TUỆ NHÂN TẠO TRONG QUẢN LÝ NHÀ TRƯỜNG - BCV NGUYỄN HỒNG DÂN</footer></section></div>';$('modal').querySelector('input,button')?.focus();}
function closeModal(){modalOpen=false;$('modal').innerHTML='';}
function authModal(){if(state.admin){modal('Tài khoản quản trị','<p class="muted">Đã đăng nhập màn điều khiển.</p><div class="actions"><button class="btn" data-action="password">Đổi mật khẩu quản trị</button><button class="btn danger" data-action="admin-logout">Đăng xuất</button></div>');return;}modal(state.initialized?'Đăng nhập điều khiển':'Khởi tạo quản trị','<form id="authForm">'+(!state.initialized?'<label class="field">Mã khởi tạo</label><input name="setup_key" type="password" required autocomplete="off">':'')+'<label class="field">Mật khẩu quản trị</label><input name="password" type="password" '+(!state.initialized?'minlength="12"':'')+' maxlength="200" required autocomplete="'+(state.initialized?'current-password':'new-password')+'"><button class="btn primary" style="margin-top:20px">'+(state.initialized?'Đăng nhập':'Khởi tạo')+'</button></form>');}
function checkinModal(login=false){if(state.me?.phone&&!login){modal('Tài khoản học viên','<div class="credentials"><h3>'+esc(state.me.name)+'</h3><p>'+esc(state.me.role)+' · '+esc(state.me.school)+'</p><p>Tài khoản: <code>'+esc(state.me.phone)+'</code></p></div><div class="actions" style="margin-top:20px"><button class="btn primary" data-action="close">Tiếp tục học</button><button class="btn" data-action="student-logout">Đăng xuất học viên</button></div>');return;}
modal(login?'Đăng nhập học viên':'Kiểm diện & vào lớp','<p class="muted">'+(login?'Dùng tài khoản số điện thoại đã đăng ký.':'Nhập đầy đủ bốn thông tin. Lưu xong thầy/cô được tạo tài khoản và tự vào lớp.')+'</p><form id="'+(login?'studentLogin':'checkinForm')+'">'+(!login?'<label class="field">Họ và tên *</label><input name="name" maxlength="100" autocomplete="name" required><label class="field">Chức vụ *</label><input name="role" maxlength="100" placeholder="Hiệu trưởng, Phó hiệu trưởng…" required><label class="field">Đơn vị *</label><input name="school" maxlength="180" autocomplete="organization" required>':'')+'<label class="field">Số điện thoại *</label><input name="phone" type="tel" inputmode="tel" maxlength="20" autocomplete="tel" required placeholder="0xxxxxxxxx">'+(login?'<label class="field">Mật khẩu</label><input name="password" type="password" required autocomplete="current-password">':'<p class="note">Thông tin phục vụ kiểm diện và tài khoản khóa học; số điện thoại chỉ xuất hiện với chính thầy/cô và quản trị.</p>')+'<div class="actions" style="margin-top:20px"><button class="btn primary">'+(login?'Đăng nhập':'Lưu & vào lớp')+'</button><button type="button" class="btn" data-action="'+(login?'register':'student-login')+'">'+(login?'Chưa có tài khoản':'Đã có tài khoản')+'</button></div></form>');}
function editor(id='',type='text',clone=false){const old=id?state.studio.items.find(x=>x.id===id):null;const x=old||{type,title:'',body:'',options:['',''],answer:0,explanation:'',seconds:30,asset:null,fit:'cover'};modal(clone?'Nhân bản nội dung':old?'Sửa nội dung':'Tạo nội dung mới','<form id="editorForm"><input type="hidden" name="id" value="'+(clone?'':esc(id))+'"><div class="grid two"><div><label class="field">Loại nội dung</label><select name="type" id="editorType">'+Object.entries(labels).map(([k,t])=>'<option value="'+k+'" '+(k===x.type?'selected':'')+'>'+t+'</option>').join('')+'</select><label class="field">Tiêu đề / câu hỏi *</label><input name="title" maxlength="160" required value="'+esc(x.title)+'"><label class="field">Nội dung / lời dẫn (dòng --- để chia trang)</label><textarea name="body" maxlength="16000" style="min-height:220px">'+esc(x.body)+'</textarea><div id="questionFields" '+(!['poll','game'].includes(x.type)?'hidden':'')+'><label class="field">Phương án (2–6, mỗi dòng một phương án)</label><textarea name="options">'+esc(x.options.join('\n'))+'</textarea><label class="field">Đáp án đúng của trò chơi</label><select name="answer">'+Array.from({length:6},(_,i)=>'<option value="'+i+'" '+(x.answer===i?'selected':'')+'>'+String.fromCharCode(65+i)+'</option>').join('')+'</select><label class="field">Thời gian trò chơi (10–300 giây)</label><input type="number" name="seconds" min="10" max="300" value="'+x.seconds+'"><label class="field">Giải thích đáp án</label><textarea name="explanation" maxlength="2000">'+esc(x.explanation)+'</textarea></div></div><div><label class="field">Tải ảnh / video / tài liệu</label><input id="uploadFile" type="file" accept=".jpg,.jpeg,.png,.webp,.gif,.mp4,.webm,.pdf,.txt,.docx"><button class="btn" type="button" data-action="upload" style="margin-top:10px">Tải tệp lên hosting</button><p class="note" id="uploadStatus">Tối đa 50 MB; giới hạn hosting có thể thấp hơn. PDF chiếu trực tiếp; DOCX tải để xem.</p><label class="field">Tư liệu đã tải</label><select name="asset" id="assetSelect"><option value="">Không dùng tư liệu</option>'+state.studio.assets.map(a=>'<option value="'+a.id+'" '+(x.asset?.id===a.id?'selected':'')+'>'+esc(a.name)+'</option>').join('')+'</select><label class="field">Ảnh / video trên màn chiếu</label><select name="fit"><option value="cover" '+(x.fit==='cover'?'selected':'')+'>Phủ kín màn hình (có thể cắt mép)</option><option value="contain" '+(x.fit==='contain'?'selected':'')+'>Hiện trọn ảnh / video</option></select><div class="info">Maket hiển thị ảnh/video toàn vùng trình chiếu. Nội dung chữ được biên tập trong biểu mẫu, không cần viết mã HTML.</div><p class="note">Nội dung đã có phản hồi được giữ nguyên; dùng Nhân bản để tạo phiên bản mới.</p></div></div><div class="actions" style="margin-top:20px"><button class="btn primary">Lưu nội dung</button>'+aiButton(['poll','game'].includes(x.type)?(x.type==='poll'?'survey':'game'):x.type==='maket'?'maket':'improve','AI hỗ trợ soạn')+'<button class="btn" type="button" data-action="close">Đóng</button></div></form>',true);}
let adminRecords=null;
async function participantModal(){adminRecords=await api('admin_data');modal('Danh sách kiểm diện','<div class="actions"><button class="btn primary" data-action="export-people">Xuất CSV</button></div><div class="table-wrap"><table><thead><tr><th>Họ tên</th><th>Chức vụ</th><th>Đơn vị</th><th>Số điện thoại</th><th>Tài khoản</th></tr></thead><tbody>'+Object.entries(adminRecords.participants).map(([id,p])=>'<tr><td>'+esc(p.name)+'</td><td>'+esc(p.role)+'</td><td>'+esc(p.school)+'</td><td>'+esc(p.phone||'Chưa cập nhật')+'</td><td>'+(p.phone?'<button class="btn small" data-action="reset-student" data-id="'+id+'">Đặt lại mật khẩu</button>':'')+'</td></tr>').join('')+'</tbody></table></div>',true);}
function credentials(r,reset=false){modal('Tài khoản đã sẵn sàng','<div class="credentials"><p>Tài khoản số điện thoại</p><code>'+esc(r.account)+'</code><p style="margin:18px 0 5px">Mật khẩu ban đầu</p><code>'+esc(r.initial_password)+'</code></div><p class="note">'+(reset?'Mật khẩu đã đặt lại theo quy tắc tên + 3 số cuối điện thoại. Gửi trực tiếp cho đúng học viên.':'Thầy/cô ghi lại để đăng nhập trên thiết bị khác. Lưu kiểm diện đã tự đăng nhập trên thiết bị này.')+'</p><button class="btn primary" data-action="close">Tiếp tục vào lớp</button>');}
function tick(){const now=Math.floor(Date.now()/1000)+serverOffset;document.querySelectorAll('[data-deadline]').forEach(e=>{const d=Number(e.dataset.deadline);e.hidden=!d;if(d){const n=Math.max(0,d-now);e.textContent=n?String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0'):'Hết giờ';}});}
async function command(op,args={}){await api('studio_control',{op,...args});await sync(true);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Đã sao chép.');}catch{modal('Sao chép nội dung','<textarea readonly>'+esc(text)+'</textarea>');}}
function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function csvCell(v){let s=String(v??'');if(/^\s*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportPeople(){const rows=[['Họ tên','Chức vụ','Đơn vị','Số điện thoại / Tài khoản','Thời điểm kiểm diện'],...Object.values(adminRecords.participants).map(p=>[p.name,p.role,p.school,p.phone||'',p.joined])];download('kiem-dien-tap-huan.csv','\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{if(a==='close'){closeModal();return;}if(a==='retry'){await sync(true);return;}if(a==='fullscreen'){if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();return;}if(!state){toast('Chưa kết nối lớp học.');return;}if(a==='ai')aiModal(b.dataset.task,b.dataset.id||'');else if(a==='project-text')await command('message',{title:b.dataset.title,body:b.dataset.body});else if(a==='ai-apply')applyAIDraft();else if(a==='ai-copy')await copy(aiDraft.title+'\n\n'+aiDraft.body);else if(a==='ai-project'){await command('message',{title:aiDraft.title+' · Bản nháp AI',body:aiDraft.body});closeModal();}else if(a==='ai-test'){b.disabled=true;toast('Đang kiểm tra kết nối AI…');try{await api('ai_generate',{task:'test',prompt:''});toast('AI đã kết nối thành công.');}finally{b.disabled=false;}}else if(a==='view'){view=b.dataset.id;render();}else if(a==='auth')authModal();else if(a==='checkin'||a==='register')checkinModal();else if(a==='student-login')checkinModal(true);else if(a==='student-logout'){await api('student_logout',{});closeModal();await sync(true);}else if(a==='admin-logout'){await api('logout',{});closeModal();await sync(true);}else if(a==='editor')editor(b.dataset.id||'',b.dataset.type||'text');else if(a==='clone')editor(b.dataset.id,'text',true);else if(a==='show'){await command('show',{id:b.dataset.id});toast('Đã đưa lên màn chiếu.');}else if(['hide','start','stop','accept','reveal'].includes(a)){await command(a,{id:b.dataset.id,value:b.dataset.value==='1'});}else if(a==='stage')await command(b.dataset.op);else if(a==='participants')await participantModal();else if(a==='export-people')exportPeople();else if(a==='reset-student'){const r=await api('studio_control',{op:'reset_student',id:b.dataset.id});credentials(r,true);}else if(a==='copy-link')await copy(learnerLink);else if(a==='session'){selectedSession=Number(b.dataset.id);selectedCourse=state.outline.find(x=>x.session===selectedSession).id;render();}else if(a==='course'){selectedCourse=b.dataset.id;courseTab='learn';render();}else if(a==='course-tab'){courseTab=b.dataset.id;render();}else if(a==='course-show'){await command('show_course',{id:b.dataset.id,page:b.dataset.page,highlight:b.dataset.highlight==null?-1:Number(b.dataset.highlight)});toast('Đã đưa nội dung lên màn chiếu.');}else if(a==='legacy-accept'||a==='legacy-reveal'){if(!state.controls.open[b.dataset.id])await api('control',{op:'open',id:b.dataset.id,value:true});await api('control',{op:a==='legacy-accept'?'accept':'reveal',id:b.dataset.id,value:b.dataset.value==='1'});await sync(true);}else if(a==='copy-prompt')await copy(state.sections.find(s=>s.id===b.dataset.id).prompt);else if(a==='item-view'){const x=state.studio.items.find(x=>x.id===b.dataset.id);modal(esc(x.title),learnerItem(x),true);}else if(a==='page')await command('page',{step:Number(b.dataset.step)});else if(a==='media')await command('media',{playing:b.dataset.playing==='1',sound:state.studio.stage.sound});else if(a==='sound')await command('media',{playing:state.studio.stage.playing,sound:!state.studio.stage.sound});else if(a==='restart')await command('media',{playing:true,sound:state.studio.stage.sound,restart:true});else if(a==='unlock-media'){const v=$('stageVideo');if(v){v.muted=!state.studio.stage.sound;await v.play();toast('Màn chiếu đã sẵn sàng phát video.');}else toast('Khi có video, bấm nút này để cho phép trình duyệt phát.');}else if(a==='upload'){const f=$('uploadFile').files[0];if(!f){toast('Chọn tệp trước.');return;}if(busy)return;busy=true;b.disabled=true;$('uploadStatus').textContent='Đang tải '+f.name+'…';try{const fd=new FormData();fd.append('file',f);fd.append('csrf',state.csrf);const r=await fetch(API+'?action=upload',{method:'POST',credentials:'same-origin',body:fd});if(r.redirected)throw Error('Tải tệp bị chuyển hướng; kiểm tra cấu hình hosting.');let v;try{v=await r.json();}catch{throw Error('Hosting chưa nhận được tệp. Kiểm tra giới hạn tải lên.');}if(!r.ok||v.error)throw Error(v.error);await sync();const o=document.createElement('option');o.value=v.asset.id;o.textContent=v.asset.name;$('assetSelect').append(o);$('assetSelect').value=v.asset.id;$('uploadStatus').textContent='Đã tải lên: '+v.asset.name;toast('Đã tải tư liệu.');}finally{busy=false;b.disabled=false;}}else if(a==='timer-modal'){modal('Đồng hồ thực hành','<form id="timerForm"><label class="field">Số phút (1–120)</label><input name="minutes" type="number" min="1" max="120" value="10" required><div class="actions" style="margin-top:18px"><button class="btn primary">Bắt đầu</button><button type="button" class="btn" data-action="timer-stop">Dừng</button></div></form>');}else if(a==='timer-stop'){await api('control',{op:'timer',seconds:0});await sync(true);closeModal();}else if(a==='announce-modal')modal('Thông báo cho lớp','<form id="announceForm"><textarea name="text" maxlength="400">'+esc(state.controls.announcement)+'</textarea><button class="btn primary" style="margin-top:18px">Cập nhật</button></form>');else if(a==='password')modal('Đổi mật khẩu quản trị','<form id="passwordForm"><label class="field">Mật khẩu hiện tại</label><input type="password" name="current" required autocomplete="current-password"><label class="field">Mật khẩu mới (ít nhất 12 ký tự)</label><input type="password" name="password" minlength="12" maxlength="200" required autocomplete="new-password"><button class="btn primary" style="margin-top:18px">Đổi mật khẩu</button></form>');}catch(err){toast(err.message);}});
document.addEventListener('change',e=>{if(e.target.id==='aiProvider'){if($('aiModel'))$('aiModel').value=e.target.value==='openai'?'gpt-4.1-mini':'gemini-2.5-flash';}if(e.target.id==='editorType')$('questionFields').hidden=!['poll','game'].includes(e.target.value);});
document.addEventListener('input',e=>{if(e.target.id==='aiKey'){const provider=e.target.value.trim().startsWith('sk-')?'openai':e.target.value.trim().startsWith('AIza')?'gemini':null;if(provider&&$('aiProvider')&&$('aiProvider').value!==provider){$('aiProvider').value=provider;$('aiModel').value=provider==='openai'?'gpt-4.1-mini':'gemini-2.5-flash';}}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(!state||busy)return;busy=true;const b=f.querySelector('button:not([type=button])');if(b)b.disabled=true;const v=Object.fromEntries(new FormData(f));try{if(f.id==='aiSettings'){await api('ai_save',v);document.activeElement?.blur();await sync(true);toast('Đã lưu khóa AI trên máy chủ.');}else if(f.id==='aiPromptForm'){if($('aiWorking'))$('aiWorking').textContent='Đang tạo bản nháp…';const r=await api('ai_generate',v);aiDraft=r.draft;if($('aiWorking'))$('aiWorking').textContent='Đã tạo xong';showAIDraft();}else if(f.id==='authForm'){await api(state.initialized?'login':'setup',v);closeModal();await sync(true);}else if(f.id==='checkinForm'){const r=await api('student_register',v);await sync(true);credentials(r);}else if(f.id==='studentLogin'){await api('student_login',v);closeModal();await sync(true);toast('Đã đăng nhập học viên.');}else if(f.id==='editorForm'){await api('studio_save',{...v,answer:Number(v.answer),seconds:Number(v.seconds),options:v.options.split('\n').map(x=>x.trim()).filter(Boolean)});closeModal();await sync(true);toast('Đã lưu nội dung. Chọn Trình chiếu để đưa lên màn hình.');}else if(f.classList.contains('voteForm')){if(!state.me?.phone){checkinModal();return;}await api('studio_vote',{id:f.dataset.id,choice:Number(v.choice)});closeModal();await sync(true);toast('Đã nhận câu trả lời.');}else if(f.id==='legacyVote'||f.id==='legacyProduct'){if(!state.me?.phone){checkinModal();return;}const old=state.mine[f.dataset.id]||{},choice=f.id==='legacyVote'?Number(v.choice):old.choice;if(!Number.isInteger(choice)){courseTab='case';toast('Chọn phương án tình huống trước khi gửi bài.');document.activeElement?.blur();render();return;}await api('submit',{id:f.dataset.id,choice,submission:v.submission??old.submission??'',link:v.link??old.link??'',share:f.id==='legacyProduct'?v.share==='on':old.share||false});document.activeElement?.blur();await sync(true);toast('Đã lưu phản hồi.');}else if(f.id==='timerForm'){await api('control',{op:'timer',seconds:Number(v.minutes)*60});closeModal();await sync(true);}else if(f.id==='announceForm'){await api('control',{op:'announcement',text:v.text});closeModal();await sync(true);}else if(f.id==='passwordForm'){await api('control',{op:'password',...v});closeModal();toast('Đã đổi mật khẩu.');}}catch(err){toast(err.message);}finally{busy=false;if(b)b.disabled=false;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(modalOpen&&e.key==='Tab'){const els=[...$('modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&!x.closest('[hidden]')),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('focusout',e=>{if(e.target.closest('#app form'))setTimeout(()=>{if(!document.activeElement?.closest('#app form'))render();},0);});
sync(true);setInterval(async()=>{if(polling||document.hidden)return;polling=true;try{await sync();}finally{polling=false;}},2000);setInterval(tick,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync(true);});
